# _pyode.py
#
# Python ODE simulation of BioNetGen model ''.
# Generated by BioNetGen C++
#
# Requires: numpy, scipy
#   pip install numpy scipy
#
# Usage:
#   python _pyode.py
#

import numpy as np
from scipy.integrate import odeint
import sys
import os

# Model dimensions
N_SPECIES = 2
N_OBSERVABLES = 2
N_REACTIONS = 1
N_PARAMETERS = 4

# Parameter names
param_names = [
    "k",
    "kr",
    "N",
    "V",
]

# Default parameters
default_parameters = np.array(
    [
        0.4,  # k
        0.2,  # kr
        20,  # N
        1,  # V
    ]
)

# Species names
species_names = [
    "A()",
    "B()",
]

# Default initial species concentrations
default_y0 = np.array(
    [
        20,  # A()
        0,  # B()
    ]
)

# Observable names
observable_names = [
    "A",
    "B",
]


def calc_expressions(parameters):
    """Calculate expressions from parameters."""
    expressions = np.zeros(4)
    expressions[0] = parameters[0]  # k
    expressions[1] = parameters[1]  # kr
    expressions[2] = parameters[2]  # N
    expressions[3] = parameters[3]  # V
    return expressions


def calc_observables(species, expressions):
    """Calculate observables from species concentrations."""
    observables = np.zeros(2)
    observables[0] = species[0]  # A
    observables[1] = species[1]  # B
    return observables


def calc_ratelaws(species, expressions, observables):
    """Calculate rate laws."""
    ratelaws = np.zeros(1)
    ratelaws[0] = rate() * species[0]
    return ratelaws


def dydt(species, t, parameters):
    """ODE right-hand side: species derivatives."""
    expressions = calc_expressions(parameters)
    observables = calc_observables(species, expressions)
    ratelaws = calc_ratelaws(species, expressions, observables)

    Dspecies = np.zeros(2)
    Dspecies[0] = -ratelaws[0]
    Dspecies[1] = ratelaws[0]

    return Dspecies


def simulate(timepoints=None, species_init=None, parameters=None):
    """Run ODE simulation and return (timepoints, species_out, observables_out)."""
    if timepoints is None:
        timepoints = np.linspace(0.5, 2, 5)
    if species_init is None:
        species_init = default_y0.copy()
    if parameters is None:
        parameters = default_parameters.copy()

    # Integrate ODEs
    species_out = odeint(
        dydt,
        species_init,
        timepoints,
        args=(parameters,),
        atol=1.000000000000000e-09,
        rtol=1.000000000000000e-08,
    )

    # Calculate observables at each timepoint
    expressions = calc_expressions(parameters)
    observables_out = np.zeros((len(timepoints), N_OBSERVABLES))
    for i in range(len(timepoints)):
        observables_out[i, :] = calc_observables(species_out[i, :], expressions)

    return timepoints, species_out, observables_out


if __name__ == "__main__":
    # Parse optional command-line arguments: t_end n_steps
    t_end = 2
    n_steps = 4
    if len(sys.argv) > 1:
        t_end = float(sys.argv[1])
    if len(sys.argv) > 2:
        n_steps = int(sys.argv[2])

    timepoints = np.linspace(0.5, t_end, n_steps + 1)
    timepoints_sim, species_out, observables_out = simulate(timepoints)

    # Write .cdat file (time + species concentrations)
    model_name = ""
    cdat_path = model_name + ".cdat"
    with open(cdat_path, "w") as f:
        # Header
        header = "{:<18s}".format("#") + "  ".join(
            (
                "{:<18s}".format("time")
                if i == 0
                else "{:<18s}".format(species_names[i - 1])
            )
            for i in range(N_SPECIES + 1)
        )
        # Actually write: first column is time
        for i in range(len(timepoints_sim)):
            line = "{:<18.12e}".format(timepoints_sim[i])
            for j in range(N_SPECIES):
                line += "  {:<18.12e}".format(species_out[i, j])
            f.write(line + "\n")
    print(f"Wrote species output to {cdat_path}")

    # Write .gdat file (time + observables)
    gdat_path = model_name + ".gdat"
    with open(gdat_path, "w") as f:
        # Header
        header = "{:<18s}".format("#          time")
        for name in observable_names:
            header += "  {:<18s}".format(name)
        f.write(header + "\n")
        for i in range(len(timepoints_sim)):
            line = "{:<18.12e}".format(timepoints_sim[i])
            for j in range(N_OBSERVABLES):
                line += "  {:<18.12e}".format(observables_out[i, j])
            f.write(line + "\n")
    print(f"Wrote observables output to {gdat_path}")
